import { ParentComponent, Show, splitProps } from "solid-js";

import { Divider } from "#core/ui-next/components/divider.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { Tooltip } from "#core/ui-next/components/tooltip.jsx";
import { ComponentRegistry } from "#core/ui-next/services/component-registry.js";

import { FramedResource, ResourceProps } from "#base/ui-next/components/framed-resource.jsx";

const ResourceTooltipComponent: ParentComponent<ResourceProps> = (props) => {
	const [local, other] = splitProps(props, [
		"resourceName",
		"resourceIcon",
		"resourceType",
		"resourceTypeIcon",
		"tooltipText",
		"resourceOrigin",
	]);
	return (
		<Tooltip
			showFiligrees={false}
			{...other}
		>
			<Tooltip.Trigger>{props.children}</Tooltip.Trigger>
			<Tooltip.Content>
				<Tooltip.Frame class="relative flex flex-col items-center bp-1 min-w-64 max-w-96">
					<div class="font-title text-secondary uppercase mb-2 flex flex-row items-center">
						<Icon
							class="size-7 mr-2"
							name={props.resourceTypeIcon}
							isUrl
						/>
						<L10n.Compose
							text="LOC_RESOURCECLASS_TOOLTIP_NAME"
							args={[Locale.compose(props.resourceType)]}
						/>
					</div>
					<div class="max-w-full flex flex-row items-center img-base-ticket-bg p-3">
						<FramedResource
							size={14}
							{...local}
						/>
						<Divider.Vertical margin={3} />

						<div class="flex flex-col shrink">
							<div class="font-title text-secondary uppercase">
								<L10n.Compose text={local.resourceName} />
							</div>
							<Divider.Horizontal
								margin={1}
								useGradient={true}
							/>
							<div class="flex flex-col">
								<L10n.Stylize text={props.tooltipText} />
								<Show when={props.resourceOrigin}>
									{(resourceOrigin) => (
										<div class="mt-1">
											<L10n.Stylize
												text="LOC_COMMERCE_EMPIRE_RESOURCES_ORIGIN_CITY"
												args={[Locale.compose(resourceOrigin())]}
											/>
										</div>
									)}
								</Show>
							</div>
						</div>
					</div>
				</Tooltip.Frame>
			</Tooltip.Content>
		</Tooltip>
	);
};

export const ResourceTooltip = ComponentRegistry.register({
	name: "ResourceTooltip",
	createInstance: ResourceTooltipComponent,
});
